function check(input, actual, expected) {
  const [nums, indexDifference, valueDifference] = input;
  if (!Array.isArray(actual) || actual.length !== 2) return false;
  const [i, j] = actual;
  if (expected[0] === -1) return i === -1 && j === -1;
  const n = nums.length;
  if (!Number.isInteger(i) || !Number.isInteger(j) || i < 0 || j < 0 || i >= n || j >= n) return false;
  return Math.abs(i - j) >= indexDifference && Math.abs(nums[i] - nums[j]) >= valueDifference;
}

