function validate([nums, indexDifference, valueDifference]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000)) return 'Each value is an integer from 0 to 10^9.';
  if (!Number.isInteger(indexDifference) || indexDifference < 0 || indexDifference > 100000) return 'indexDifference is an integer from 0 to 10^5.';
  if (!Number.isInteger(valueDifference) || valueDifference < 0 || valueDifference > 1000000000) return 'valueDifference is an integer from 0 to 10^9.';
  return null;
}

