function findIndices(nums, indexDifference, valueDifference) {
  let minIndex = 0;
  let maxIndex = 0;
  for (let j = indexDifference; j < nums.length; j++) {
    const i = j - indexDifference;
    if (nums[i] < nums[minIndex]) {
      minIndex = i;
    }
    if (nums[i] > nums[maxIndex]) {
      maxIndex = i;
    }
    if (nums[j] - nums[minIndex] >= valueDifference) {
      return [minIndex, j];
    }
    if (nums[maxIndex] - nums[j] >= valueDifference) {
      return [maxIndex, j];
    }
  }
  return [-1, -1];
}

