function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = pick(1, 8);
    const top = rand() < 0.5 ? 3 : 10;
    const nums = Array.from({ length: n }, () => pick(0, top));
    return [nums, pick(0, n + 1), pick(0, top + 2)];
  }
  const n = 2000;
  const mode = rand();
  if (mode < 0.35) {
    // Values packed into a narrow band so that no pair is far enough apart: a full scan.
    const nums = Array.from({ length: n }, () => pick(500, 1500));
    return [nums, pick(0, 1000), 1001];
  }
  if (mode < 0.7) {
    const nums = Array.from({ length: n }, () => pick(0, 1000000));
    return [nums, pick(1500, 1999), pick(990000, 1000000)];
  }
  const nums = Array.from({ length: n }, () => pick(0, 1000000000));
  return [nums, pick(0, 2100), pick(0, 1000000000)];
}
